{"implementation":"def solve(case):
    import math

    if not isinstance(case, dict):
        raise ValueError("case must be an object")
    if "nodes" not in case or "required_symbols" not in case:
        raise ValueError("missing required case field")

    nodes = case["nodes"]
    required_symbols = case["required_symbols"]
    if not isinstance(nodes, list) or not nodes:
        raise ValueError("nodes must be a non-empty array")
    if not isinstance(required_symbols, list):
        raise ValueError("required_symbols must be an array")
    if any(not isinstance(symbol, str) for symbol in required_symbols):
        raise ValueError("required symbols must be strings")

    by_id = {}
    normalized = []
    required_node_fields = ("id", "parent", "symbol", "depth", "removable", "utility")
    for node in nodes:
        if not isinstance(node, dict):
            raise ValueError("each node must be an object")
        if any(field not in node for field in required_node_fields):
            raise ValueError("node is missing a required field")

        node_id = node["id"]
        parent = node["parent"]
        symbol = node["symbol"]
        depth = node["depth"]
        removable = node["removable"]
        utility = node["utility"]

        if not isinstance(node_id, str) or node_id in by_id:
            raise ValueError("node IDs must be unique strings")
        if parent is not None and not isinstance(parent, str):
            raise ValueError("parent must be a node ID or null")
        if not isinstance(symbol, str):
            raise ValueError("symbol must be a string")
        if isinstance(depth, bool) or not isinstance(depth, int) or depth < 0:
            raise ValueError("depth must be a non-negative integer")
        if not isinstance(removable, bool):
            raise ValueError("removable must be boolean")
        if isinstance(utility, bool) or not isinstance(utility, (int, float)) or not math.isfinite(utility):
            raise ValueError("utility must be a finite number")

        copied = {
            "id": node_id,
            "parent": parent,
            "symbol": symbol,
            "depth": depth,
            "removable": removable,
            "utility": utility,
        }
        by_id[node_id] = copied
        normalized.append(copied)

    roots = [node for node in normalized if node["parent"] is None]
    if len(roots) != 1 or roots[0]["depth"] != 0:
        raise ValueError("nodes must contain exactly one depth-zero root")
    root_id = roots[0]["id"]

    children = {node_id: [] for node_id in by_id}
    for node in normalized:
        parent = node["parent"]
        if parent is None:
            continue
        if parent not in by_id or parent == node["id"]:
            raise ValueError("invalid parent reference")
        if node["depth"] != by_id[parent]["depth"] + 1:
            raise ValueError("node depth is inconsistent with its parent")
        children[parent].append(node["id"])

    visited = set()
    pending = [root_id]
    while pending:
        node_id = pending.pop()
        if node_id in visited:
            raise ValueError("nodes must form a tree")
        visited.add(node_id)
        pending.extend(children[node_id])
    if len(visited) != len(normalized):
        raise ValueError("nodes must form one connected tree")

    required = set(required_symbols)
    symbol_counts = {}
    for node in normalized:
        symbol = node["symbol"]
        symbol_counts[symbol] = symbol_counts.get(symbol, 0) + 1
    if any(symbol_counts.get(symbol, 0) == 0 for symbol in required):
        raise ValueError("a required symbol is not represented")

    retained = set(by_id)
    removed = []
    candidates = sorted(normalized, key=lambda node: (-node["depth"], node["id"]))
    for node in candidates:
        node_id = node["id"]
        symbol = node["symbol"]
        if node_id == root_id or not node["removable"]:
            continue
        if any(child_id in retained for child_id in children[node_id]):
            continue
        if symbol in required and symbol_counts[symbol] <= 1:
            continue
        retained.remove(node_id)
        symbol_counts[symbol] -= 1
        removed.append(node_id)

    return {
        "removed_node_ids": removed,
        "retained_node_ids": sorted(retained),
    }
"}
